values ('21b86b20-4902-4f6a-89ba-9312ef1ca5dc', 'f34a2607-06a3-4c4b-8e3d-2315bc92afb5', 'How Building Wellness Apps Changed My Own Habits', 10, 'Format: Storytelling with reflection Type: Business / Personal Hook: “When you spend years building wellness apps, you can’t ignore your own health. I started practicing what we preach — from sleep tracking to mindful breaks — and it changed how I work and live.”', null, 'posted', '2025-10-24T12:00:00Z', '2025-10-24T12:00:00Z');
