insert into public.posts (id, campaign_id, theme, position, body, linkedin_url, status, scheduled_at, posted_at)
values ('c252c60e-fcfa-4b46-82ff-bcfda3fe5ad0', 'f34a2607-06a3-4c4b-8e3d-2315bc92afb5', 'Small detail, big user impact (the time zone story)', 17, 'Type: LI Company Post Text Post Idea: Share the story of how a small tweak (auto-detecting time zones) solved a huge issue for vendors, reducing support tickets by 90% and improving trust. Hook: “Do big changes always need big solutions? Sometimes, the most powerful impact comes from fixing one tiny detail.” Format: Text post with a simple visual (before/after screenshot or illustration).', 'https://www.linkedin.com/posts/mykyta-shevchenko-ciphercross-wellness_a-few-months-ago-our-support-team-started-activity-7441744321499877376-NaJk?utm_source=share&utm_medium=member_desktop&rcm=ACoAACKi8XsB9WBoWK1z6g7nRgrBaW3-4QoyJT8', 'posted', '2026-03-23T06:15:00Z', '2026-03-23T06:15:00Z');
