values ('a8cba5b7-2cf6-4de8-9e66-07387cd40b83', '969b6828-7641-4509-9a99-50ec4877e157', 'Resilience in uncertain times', 9, 'Format: Motivational / reflection Type: Personal Hook: “The last 2 years taught me: uncertainty is permanent. Resilience isn’t about predicting the future, but adapting to whatever comes.”', null, 'posted', '2025-09-22T12:00:00Z', '2025-09-22T12:00:00Z');
