values ('9e846035-4fff-4111-b251-978cc8fd4826', '969b6828-7641-4509-9a99-50ec4877e157', 'Choosing Challenges That Matter', 12, 'Text Post Idea: Explain how you choose projects — only those aligned with values, not vanity metrics. The wellness space needs integrity, not noise. Hook: “Not every challenge deserves your energy — especially if it’s driven by ego, not purpose.” Format (Optional): Reflection post CTA: “How do you decide which challenges are worth your time?”', null, 'posted', null, null);
insert into public.posts (id, campaign_id, theme, position, body, linkedin_url, status, scheduled_at, posted_at)
values ('630411a8-2101-4b45-8769-547f4208e20b', '969b6828-7641-4509-9a99-50ec4877e157', 'The Message That Changed My Perspective', 13, 'Text Post Idea: Tell the story of the user who said your app’s short breathing rituals helped stop their daily panic attacks. Emphasize that impact comes from simplicity and emotional safety, not fancy features. Hook: “A few minutes of calm can change a life. We saw it happen.” Format (Optional): Storytelling (situation → reflection → insight) CTA: “What’s one small digital habit that helps you feel calmer?”', null, 'posted', null, null);
