insert into public.posts (id, campaign_id, theme, position, body, linkedin_url, status, scheduled_at, posted_at)
values ('85d0b5ed-75fb-48fe-8eca-35fc5489846e', '969b6828-7641-4509-9a99-50ec4877e157', 'One random travel habit I keep', 24, 'Type: LI Personal Post Text Post Idea: “When I travel even for work I always find one local coffee spot and go there every morning. It’s a small way to slow down, meet people, and feel grounded. Routine in unfamiliar places helps me think clearer.”  Hook: “The first thing I do in any new city: find my coffee spot.”', 'https://www.linkedin.com/posts/mykyta-shevchenko-ciphercross_the-first-thing-i-do-in-any-new-city-find-activity-7442846567696351232-raJC?utm_source=share&utm_medium=member_desktop&rcm=ACoAAD1GaXQBLC3IwzuWDrLQoIsrw5Y1tC2y1Xs', 'posted', '2026-03-26T07:15:00Z', '2026-03-26T07:15:00Z');
