insert into public.posts (id, campaign_id, theme, position, body, linkedin_url, status, scheduled_at, posted_at)
values ('6b1ae2c7-b58f-4311-950b-e211003dbbec', '969b6828-7641-4509-9a99-50ec4877e157', 'The playlist that helps me focus', 25, 'Type: LI Personal Post Text Post Idea: “Whenever I work on a new product idea, I listen to the same playlist - calm piano and ambient sounds. Music became my mental signal: time to focus. Funny how one small habit can instantly switch your brain into flow mode.”  Hook: “One playlist that instantly gets me into focus mode.”', 'https://www.linkedin.com/posts/mykyta-shevchenko-ciphercross_deep-focus-activity-7444273504960565248-_McY?utm_source=share&utm_medium=member_desktop&rcm=ACoAAD1GaXQBLC3IwzuWDrLQoIsrw5Y1tC2y1Xs', 'posted', '2026-03-30T06:45:00Z', '2026-03-30T06:45:00Z');
insert into public.post_stats (post_id, views, likes, comments, recorded_at)
