insert into public.posts (id, campaign_id, theme, position, body, linkedin_url, status, scheduled_at, posted_at)
values ('9d0c8133-946a-46e0-a1d5-8805763a6b1e', '969b6828-7641-4509-9a99-50ec4877e157', 'Personal Routine as a Founder', 27, 'Type: LI Personal Post Text Post Idea: Share a real daily/weekly routine focused on maintaining mental clarity while building a company in the wellness space. Hook: Building wellness products forces you to question your own habits first Format (Optional): Structured list (morning / work / reset habits)', 'https://www.linkedin.com/posts/mykyta-shevchenko-ciphercross_building-wellness-products-forces-you-to-activity-7445371979286605825-vbkn?utm_source=share&utm_medium=member_desktop&rcm=ACoAAD1GaXQBLC3IwzuWDrLQoIsrw5Y1tC2y1Xs', 'posted', '2026-04-02T07:30:00Z', '2026-04-02T07:30:00Z');
