insert into public.posts (id, campaign_id, theme, position, body, linkedin_url, status, scheduled_at, posted_at)
values ('c21a447c-a074-4e76-bcaa-855bee2aaceb', '62b02c62-e03e-4c72-9fc7-058c87b3d847', 'Meet the People Who Build Wellness', 8, 'Some places stay with you long after the trip ends. For me, it was Asia.

That journey became a turning point, not just a change of scenery, but a shift in how I saw life and work.
Far away from daily tasks, I finally had the distance to take a “helicopter view” of everything I was doing.

I realized something simple but powerful: if you want to make a real impact, you can’t do it alone.
One set of hands, one mind - that’s a start, but not enough to reach as many people as your vision could.

That’s when the idea of building a team first took shape in my head.
A group of people who share the same values, passion, and curiosity to make wellness technology actually help people live better.

Today, that idea turned into what we build at CipherCross - user-centric wellness products that combine empathy with scalable, secure tech.

And every time I look back at that trip, I’m reminded that the best journeys start when you step away… to see the bigger picture.

What place or moment made you see things from a different angle?', null, 'approved', null, null);
insert into public.posts (id, campaign_id, theme, position, body, linkedin_url, status, scheduled_at, posted_at)
values ('8d519d61-44f4-4834-9df2-8600e12a5ba0', '62b02c62-e03e-4c72-9fc7-058c87b3d847', 'Wellness App Security: Why HIPAA Compliance Is Non-Negotiable', 9, 'Format: Expert Q&A / Insight Article  Type: Tech / Expertise  Hook: In digital health, trust starts with privacy. Here’s how CipherCross goes beyond checklists and makes HIPAA compliance a built-in part of every wellness product—from day one, not just at launch.  Body idea: Share real examples of how CipherCross has implemented security protocols, anonymized data, and kept client/user trust at the center. Mention 100% HIPAA-compliant delivery as an achievement.  CTA: → Want to see what secure wellness should look like in practice? Contact us for a walkthrough.', 'https://www.linkedin.com/feed/update/urn:li:activity:7446802628681912320', 'posted', '2026-04-06T06:15:00Z', '2026-04-06T06:15:00Z');
