insert into public.posts (id, campaign_id, theme, position, body, linkedin_url, status, scheduled_at, posted_at)
values ('54a5d961-549e-482c-ae52-935acb5c6e56', '62b02c62-e03e-4c72-9fc7-058c87b3d847', 'The Hidden Psychology of Consistency', 13, 'Text Post Idea: Most wellness apps lose users not because of weak features — but because of emotional friction. Here’s how behavioral design keeps users engaged: 1️⃣ Emotional mapping – Design flows that reflect real moods, not just goals. 2️⃣ Micro-accomplishments – Celebrate small wins to sustain momentum. 3️⃣ Gentle nudges – Encourage, don’t guilt. At CipherCross, we craft UX that supports human rhythm — because consistency is emotional before it’s behavioral. Hook: “Most users don’t quit — they disconnect.” Format (Optional): Carousel “3 Design Secrets That Keep Users Engaged”', 'https://www.linkedin.com/feed/update/urn:li:activity:7441755748641968128', 'posted', '2026-03-23T06:00:00Z', '2026-03-23T06:00:00Z');
