insert into public.posts (id, campaign_id, theme, position, body, linkedin_url, status, scheduled_at, posted_at)
values ('72fd3c26-6f6a-458d-abcc-2bbbadd45067', '62b02c62-e03e-4c72-9fc7-058c87b3d847', '5 User Interaction Mistakes That Break Trust', 14, 'Type: LI Useful Post Text Post Idea: Even the most advanced wellness app can fail if users don’t feel respected or understood. Here are 5 mistakes that quietly destroy trust: 1️⃣ Mandatory signup before showing value. 2️⃣ Vague consent and unclear data flows. 3️⃣ Notification overload. 4️⃣ Ignoring accessibility and offline modes. 5️⃣ Copy-pasting web patterns into mobile without context.  At CipherCross, we design with empathy, compliance, and clarity — because wellness apps should feel safe, not stressful.  Hook: “Good UX doesn’t shout. It earns trust quietly.” Format: Single-slide carousel (title + 5 simple icons).', 'https://www.linkedin.com/feed/update/urn:li:activity:7442472954174570496', 'posted', '2026-03-25T06:30:00Z', '2026-03-25T06:30:00Z');
