insert into public.posts (id, campaign_id, theme, position, body, linkedin_url, status, scheduled_at, posted_at)
values ('5f5d8b53-1ee2-43b4-9d17-cd04bc3c3ea1', '62b02c62-e03e-4c72-9fc7-058c87b3d847', 'The Hidden Cost of Poor Data Architecture in Wellness Products', 37, 'Hook: Most wellness startups underestimate how technical decisions today shape business risks tomorrow Text Post Idea: Explain how fragmented data storage, legacy integrations, and unscalable backend structures later lead to:  Security risks in health data  Poor personalization  High maintenance cost  Slow feature deployment  Show why wellness products need architecture thinking from the first MVP stage.  Format: Short insights list + problem → solution framing', null, 'posted', '2026-05-21T06:15:00Z', '2026-05-21T06:15:00Z');
