insert into public.posts (id, campaign_id, theme, position, body, linkedin_url, status, scheduled_at, posted_at)
values ('94c8202d-7f3a-491f-b94c-1503d9ef0569', '62b02c62-e03e-4c72-9fc7-058c87b3d847', 'How to Turn Health Data into Real User Value', 43, 'Type: LI Useful Post Text Post Idea: Пояснити різницю між “collecting data” vs “creating value”. Як правильно працювати з даними: what to track, what to ignore, як не перевантажити юзера. Мінімальний data framework.  Hook: Collecting health data is easy Turning it into value is where most apps fail  Format (Optional): Mini-guide', null, 'posted', '2026-06-04T05:30:00Z', '2026-06-04T05:30:00Z');
