insert into public.posts (id, campaign_id, theme, position, body, linkedin_url, status, scheduled_at, posted_at)
values ('0b9f9da1-e84b-4e47-bb3c-5183806ae277', '9dfea31b-3802-4281-a13f-d4313e15631c', 'Personal intro + role', 0, 'Text Post Idea: Short personal introduction: who Anastasiya is, current role, what she does at CipherCross, 3 concrete numbers/metrics (years in SDR, meetings booked per month, conversion improvement). Call-to-action: ask which onboarding pain point they face. Hook: Hi, I''m Anastasiya — I help Wellness & HealthTech teams turn cold interest into meetings that actually convert Format: Short paragraph + 3-line bullet list of metrics', null, 'posted', '2026-06-10T15:30:00Z', '2026-06-10T15:30:00Z');
insert into public.posts (id, campaign_id, theme, position, body, linkedin_url, status, scheduled_at, posted_at)
values ('d204ff34-a3aa-4dcd-9043-b9f8971bbb71', '9dfea31b-3802-4281-a13f-d4313e15631c', '3 shifts I’m seeing in digital health outreach — and one short message that actually works', 1, 'Body: I’ve been tracking how HealthTech buyers respond to outreach, and three clear shifts stand out:  Relevance beats frequency. Generic cadences get filtered out. Buyers respond when you reference a specific role, recent event, or a concrete challenge they’re facing.  Brevity is respect. Short, useful messages (read time \< 2 minutes) outperform long pitches that demand time they don’t have.  Social proof matters more than pushy sequences. Peers, short case snippets, and contextual results open doors faster than scripted follow-ups.  What this means for outreach: cut the templates, lead with insight, and give immediate value. Below is a compact core message that feels human and gets replies.', null, 'posted', '2026-06-11T06:00:00Z', '2026-06-11T06:00:00Z');
insert into public.posts (id, campaign_id, theme, position, body, linkedin_url, status, scheduled_at, posted_at)
values ('1c810792-470b-42a9-bfb6-c18a66bfb77c', '9dfea31b-3802-4281-a13f-d4313e15631c', 'Patterns I keep seeing in healthtech/wellness products, and a small fix that moved the needle', 2, 'Body: Many teams drive lots of web traffic, then watch users disappear before they ever activate the app. From product research across health and wellness products I keep noticing the same pattern:  Problem: high-quality web visits, low mobile activation. Users click through content but drop off when asked to download, sign up, or complete onboarding flows.  Solution: a two-part intervention — a small onboarding UX fix (reduce steps, clear value-first copy) plus a short, personalized outreach nudge to warm leads (email or in-app message linking the exact next step).  Result: in an anonymized mini-case we saw activation rise from the low teens to the mid-20s (% range), and DAU improve by roughly 15–30% after the combined change.  Takeaway: sometimes a tiny product change + targeted human follow-up unlocks trapped value from existing traffic.', null, 'approved', '2026-06-16T05:30:00Z', null);
insert into public.posts (id, campaign_id, theme, position, body, linkedin_url, status, scheduled_at, posted_at)
values ('8e32546d-4e7e-4f5a-9e3d-e690df9a56d1', '9dfea31b-3802-4281-a13f-d4313e15631c', 'Not every lead deserves a demo - how I quickly judge if a HealthTech/Wellness prospect is worth deeper attention', 3, 'Body: I use a hybrid approach to qualify HealthTech and wellness leads fast — choosing BANT when basics matter, MEDDPICC for enterprise complexity, and persona-based checks when buyer signals are thin. Here’s how I think about each and what I scan for on first contact.  Frameworks (quick comparison)  BANT — When to use: early-stage deals or SMB buyers; What I check: Budget availability, Authority of contact, Need clarity, Timeline realism.  MEDDPICC — When to use: mid-enterprise and hospital systems; What I check: Metrics (impact), Economic buyer identified, Decision criteria, Decision process, Paper process, Identify pain, Champion presence, Competition landscape.  Persona-based — When to use: thin signals or product-led interest; What I check: role-specific priorities (CIO vs Head of Nursing), recent activity or content signals, likely short-term wins they care about.  Three quick qualification questions I ask (works as LinkedIn or opening email)  What outcome would make this project a success for you in 90 days? (tests clarity of need + timeline)  Who else needs to sign off or influence this decision? (reveals stakeholders / whether a champion exists)  What budget or funding window is allocated for this initiative? (fast budget signal; can be a range)  How I use the answers  If timeline is vague, stakeholders unknown, and no budget hint → deprioritize or move to light nurture.  If outcome is clear, an economic buyer is named, and a near-term funding window exists → qualify for discovery/demo.  If role signals point to operational pain (Head of Nursing) vs strategic ROI (CIO), I tailor next outreach: tactical pilot vs ROI case study.  Micro-runbook (30–60s scan)  Look at company size, recent news, and the contact’s role/activity.  Send a one-sentence value check + the first qualification question.  If reply gives 2 of 3 strong signals (clear outcome, stakeholder, budget) — book discovery.', null, 'approved', '2026-06-18T16:00:00Z', null);
insert into public.posts (id, campaign_id, theme, position, body, linkedin_url, status, scheduled_at, posted_at)
